#pragma once

// The main() of every boundary fuzz binary.
//
// A harness source defines LLVMFuzzerTestOneInput and crucible_fuzz_seeds,
// and then includes this header with CRUCIBLE_FUZZ_STANDALONE_MAIN defined.
// The seeds are generated by the harness from the real writers, so a format
// change moves the seeds with it.  The binary runs in one of these modes:
//
//   <binary> FILE                 feeds FILE once
//   <binary> DIR [--mutate=N]     feeds every file in DIR and every seed
//   <binary> --mutate=N           feeds every seed, then N mutated copies,
//                                 from a fixed stream (the ctest smoke run)
//   <binary> ... --crash-file=P   writes the input in flight to P when a
//                                 claim, a contract or a sanitizer stops
//                                 the process
//   <binary> --write-seeds=DIR    writes the seeds to DIR, for afl-fuzz -i
//   <binary>                      AFL++ persistent mode, when the binary was
//                                 built with afl-g++-fast: the input comes
//                                 from shared memory, 10000 inputs per fork
//
// The mutation mode has no coverage feedback.  It only makes the smoke run
// reach past the seeds.  Coverage-guided runs use afl-fuzz, see
// test/fuzz/README.md and test/fuzz/run-afl.sh.

#ifdef CRUCIBLE_FUZZ_STANDALONE_MAIN

#include <algorithm>
#include <array>
#include <csignal>
#include <cstdint>
#include <cstdio>
#include <cstdlib>
#include <cstring>
#include <filesystem>
#include <fstream>
#include <iterator>
#include <span>
#include <string_view>
#include <vector>

#include <fcntl.h>
#include <sanitizer/common_interface_defs.h>
#include <unistd.h>

#ifdef __AFL_HAVE_MANUAL_CONTROL
#pragma GCC diagnostic push
#pragma GCC diagnostic ignored "-Wold-style-cast"
#pragma GCC diagnostic ignored "-Wcast-qual"
#pragma GCC diagnostic ignored "-Wconversion"
#pragma GCC diagnostic ignored "-Wsign-conversion"
#pragma GCC diagnostic ignored "-Wuseless-cast"
#pragma GCC diagnostic ignored "-Wmissing-declarations"
#pragma GCC diagnostic ignored "-Wextra-semi"
#pragma GCC diagnostic ignored "-Wpedantic"
__AFL_FUZZ_INIT();
#pragma GCC diagnostic pop
#endif

namespace crucible::fuzz::boundary {

[[nodiscard]] inline std::vector<std::uint8_t> read_file_bytes(const std::filesystem::path& p) {
    std::ifstream f(p, std::ios::binary);
    return std::vector<std::uint8_t>{std::istreambuf_iterator<char>(f), std::istreambuf_iterator<char>()};
}

// splitmix64: a fixed, portable stream, so the smoke run is the same run on
// every host.
[[nodiscard]] inline std::uint64_t next_random(std::uint64_t& state) noexcept {
    std::uint64_t z = (state += 0x9E3779B97F4A7C15ULL);
    z = (z ^ (z >> 30)) * 0xBF58476D1CE4E5B9ULL;
    z = (z ^ (z >> 27)) * 0x94D049BB133111EBULL;
    return z ^ (z >> 31);
}

// Applies one to eight byte-level edits: flip a bit, set a byte to an edge
// value, insert a byte, delete a byte, or splice in a run of the donor.
inline void mutate(std::vector<std::uint8_t>& bytes, std::span<const std::uint8_t> donor, std::uint64_t& state) {
    static constexpr std::uint8_t kEdges[] = {0x00, 0x01, 0x7F, 0x80, 0xFF, 0xFE, 0x10, 0x40};
    const std::uint64_t edits = 1 + next_random(state) % 8;
    for (std::uint64_t e = 0; e < edits; ++e) {
        const std::uint64_t r = next_random(state);
        const std::size_t at = bytes.empty() ? 0 : (r >> 8) % bytes.size();
        switch (r % 5) {
            case 0:
                if (!bytes.empty()) bytes[at] = static_cast<std::uint8_t>(bytes[at] ^ (1U << ((r >> 4) % 8)));
                break;
            case 1:
                if (!bytes.empty()) bytes[at] = kEdges[(r >> 4) % std::size(kEdges)];
                break;
            case 2:
                bytes.insert(bytes.begin() + static_cast<std::ptrdiff_t>(at), static_cast<std::uint8_t>(r >> 16));
                break;
            case 3:
                if (!bytes.empty()) bytes.erase(bytes.begin() + static_cast<std::ptrdiff_t>(at));
                break;
            default:
                if (!donor.empty()) {
                    const std::size_t from = (r >> 20) % donor.size();
                    const std::size_t len = std::min<std::size_t>(1 + (r >> 40) % 64, donor.size() - from);
                    bytes.insert(bytes.begin() + static_cast<std::ptrdiff_t>(at),
                                 donor.begin() + static_cast<std::ptrdiff_t>(from),
                                 donor.begin() + static_cast<std::ptrdiff_t>(from + len));
                }
                break;
        }
    }
}

// The input in flight, and the file that receives it when the process
// dies.  The path is copied into a fixed buffer at startup, so the death
// path calls only async-signal-safe functions.
inline std::span<const std::uint8_t> current_input;
inline std::array<char, 4096> crash_path{};

inline void save_current_input() noexcept {
    if (crash_path[0] == '\0') return;
    const int fd = ::open(crash_path.data(), O_CREAT | O_WRONLY | O_TRUNC | O_CLOEXEC, 0644);
    if (fd < 0) return;
    std::size_t done = 0;
    while (done < current_input.size()) {
        const ssize_t n = ::write(fd, current_input.data() + done, current_input.size() - done);
        if (n <= 0) break;
        done += static_cast<std::size_t>(n);
    }
    (void)::close(fd);
}

inline void on_abort_signal(int signal_number) noexcept {
    save_current_input();
    (void)std::signal(signal_number, SIG_DFL);
    (void)std::raise(signal_number);
}

// A claim and a contract end in abort, and a sanitizer report ends in its
// death callback.  Both save the input in flight.
inline void arm_crash_file(const char* path) noexcept {
    const std::size_t n = std::min(std::strlen(path), crash_path.size() - 1);
    std::memcpy(crash_path.data(), path, n);
    crash_path[n] = '\0';
    (void)std::signal(SIGABRT, &on_abort_signal);
    __sanitizer_set_death_callback(&save_current_input);
}

inline void feed(std::span<const std::uint8_t> bytes) {
    current_input = bytes;
    (void)LLVMFuzzerTestOneInput(bytes.data(), bytes.size());
}

inline int write_seeds(const std::filesystem::path& dir) {
    std::filesystem::create_directories(dir);
    const auto seeds = crucible_fuzz_seeds();
    for (std::size_t i = 0; i < seeds.size(); ++i) {
        std::ofstream out(dir / ("seed-" + std::to_string(i)), std::ios::binary | std::ios::trunc);
        out.write(static_cast<const char*>(static_cast<const void*>(seeds[i].data())),
                  static_cast<std::streamsize>(seeds[i].size()));
    }
    std::fprintf(stderr, "fuzz: wrote %zu seeds to %s\n", seeds.size(), dir.c_str());
    return 0;
}

// arg is a file, a directory, or null for the generated seeds only.
inline int run_corpus_or_file(const char* arg, std::uint64_t mutations) {
    std::vector<std::vector<std::uint8_t>> seeds = crucible_fuzz_seeds();
    if (arg != nullptr) {
        const std::filesystem::path p{arg};
        if (std::filesystem::is_regular_file(p)) {
            const auto buf = read_file_bytes(p);
            std::fprintf(stderr, "fuzz: %s (%zu bytes)\n", arg, buf.size());
            feed(buf);
            return 0;
        }
        if (!std::filesystem::is_directory(p)) {
            std::fprintf(stderr, "fuzz: '%s' is neither a regular file nor a directory\n", arg);
            return 1;
        }
        for (const auto& entry : std::filesystem::directory_iterator(p)) {
            if (entry.is_regular_file()) seeds.push_back(read_file_bytes(entry.path()));
        }
    }
    // The walk order of a directory depends on the file system.  Sorting
    // keeps the mutation stream the same on every host.
    std::ranges::sort(seeds);
    if (seeds.empty()) seeds.emplace_back();

    for (const auto& seed : seeds)
        feed(seed);

    std::uint64_t state = 0x6372756369626c65ULL;
    for (std::uint64_t i = 0; i < mutations; ++i) {
        const auto& base = seeds[next_random(state) % seeds.size()];
        const auto& donor = seeds[next_random(state) % seeds.size()];
        std::vector<std::uint8_t> bytes = base;
        mutate(bytes, donor, state);
        feed(bytes);
    }
    std::fprintf(stderr, "fuzz: replayed %zu seeds and %llu mutations\n", seeds.size(),
                 static_cast<unsigned long long>(mutations));
    return 0;
}

}  // namespace crucible::fuzz::boundary

int main(int argc, char** argv) {
#ifdef __AFL_HAVE_MANUAL_CONTROL
    if (argc < 2) {
#pragma GCC diagnostic push
#pragma GCC diagnostic ignored "-Wold-style-cast"
#pragma GCC diagnostic ignored "-Wcast-qual"
#pragma GCC diagnostic ignored "-Wconversion"
#pragma GCC diagnostic ignored "-Wsign-conversion"
#pragma GCC diagnostic ignored "-Wuseless-cast"
#pragma GCC diagnostic ignored "-Wpedantic"
        __AFL_INIT();
        unsigned char* buf = __AFL_FUZZ_TESTCASE_BUF;
        while (__AFL_LOOP(10000)) {
            const auto len = static_cast<std::size_t>(__AFL_FUZZ_TESTCASE_LEN);
            (void)LLVMFuzzerTestOneInput(buf, len);
        }
#pragma GCC diagnostic pop
        return 0;
    }
#endif
    if (argc < 2) {
        std::fprintf(stderr,
                     "Usage: %s [FILE | DIR] [--mutate=N] [--crash-file=PATH] | --write-seeds=DIR\n"
                     "  FILE              feeds the bytes of FILE once.\n"
                     "  DIR               feeds every file in DIR and every generated seed.\n"
                     "  --mutate=N        also feeds N mutated copies of the seeds.\n"
                     "  --crash-file=PATH writes the input in flight to PATH if the process dies.\n"
                     "  --write-seeds=DIR writes the generated seeds to DIR.\n",
                     argv[0]);
        return 1;
    }
    const char* target = nullptr;
    std::uint64_t mutations = 0;
    for (int i = 1; i < argc; ++i) {
        const std::string_view flag{argv[i]};
        if (flag.starts_with("--mutate=")) {
            mutations = std::strtoull(argv[i] + 9, nullptr, 10);
        } else if (flag.starts_with("--crash-file=")) {
            crucible::fuzz::boundary::arm_crash_file(argv[i] + 13);
        } else if (flag.starts_with("--write-seeds=")) {
            return crucible::fuzz::boundary::write_seeds(std::filesystem::path{argv[i] + 14});
        } else {
            target = argv[i];
        }
    }
    return crucible::fuzz::boundary::run_corpus_or_file(target, mutations);
}

#endif  // CRUCIBLE_FUZZ_STANDALONE_MAIN
